interface Order { id: number; items: string[] }
type Id = Order["id"];

function firstItem(order: Order): string {
  const item = order.items[0];
  if (item === undefined) {
    throw new Error(`order ${order.id} is empty`);
  }
  return item;
}

const id: Id = 7;
console.log(new Map<string, number>([["a", 1]]).size, [1, 2, 3].at(-1));
console.log(firstItem({ id, items: [] }));

